window.AUTH=window.AUTH||{};window.AUTH["23-217"]={"d":"23-217","id":"2024/23-217","n":"E.M.D. Sales, Inc. v. Carrera","briefs":[{"k":"petitioner","label":"Brief of petitioners E.M.D. Sales, Inc., et al.","date":"2024-08-13","url":"https://www.supremecourt.gov/DocketPDF/23/23-217/322348/20240813135114449_EMD%20Brief%20for%20Petitioners.pdf","side":"pet","n":65},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2024-08-20","url":"https://www.supremecourt.gov/DocketPDF/23/23-217/322958/20240820155150988_23-217tsacUnitedStates.pdf","side":"us","n":45},{"k":"respondent","label":"Brief of respondents Faustino Sanchez Carrera, et al.","date":"2024-09-24","url":"https://www.supremecourt.gov/DocketPDF/23/23-217/326778/20240924155125392_2024.09.24%20EMD%20v%20Carrera%20-%20Brief%20for%20Respondents.pdf","side":"res","n":46},{"k":"reply","label":"Reply of petitioners E.M.D. Sales, Inc., et al.","date":"2024-10-22","url":"https://www.supremecourt.gov/DocketPDF/23/23-217/328931/20241022125500199_EMD%20Reply%20Brief%20for%20Petitioners%20-%20Final.pdf","side":"pet","n":37}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us1r06_5ifl.pdf","tr":true,"items":[{"t":"case","label":"Addington v. Texas","cite":"441 U.S. 418","y":1979,"id":"1978/77-5992","sc":1,"op":1,"ar":3,"sum":"The Court held that the standard of proof required in a civil case involving involuntary commitment to a mental health facility must be higher than a preponderance of the evidence, but that the “beyond a reasonable doubt” standard was not constitutionally required.","sumSrc":"Oyez","by":{"0":"2-3, 13-15, 18, 20-22","1":"8-10, 13","2":"12, 13, 14, 15"}},{"t":"case","label":"Baker v. Upson Reg’l Med. Ctr.","cite":"94 F.4th 1312","y":2024,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/94/1312/","by":{"0":"21"}},{"t":"case","label":"California ex rel Cooper v. Mitchell Bros.’ Santa Ana Theater","cite":"454 U.S. 90","y":1981,"id":"1981/81-271","sc":1,"sum":"A city, in a public nuisance abatement action against a motion picture theater, is not required, as a matter of constitutional law, to establish the obscenity of the motion pictures at issue by proof \"beyond a reasonable doubt.\" While a State may require such proof in such a case, that choice is solely a matter of state law and is not required by the First and Fourteenth Amendments. Although this Court has held that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14, 18, 20","3":"4"}},{"t":"case","label":"Carroll v. Del. River Port Auth.","cite":"843 F.3d 129","y":2016,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/843/129/","by":{"0":"21"}},{"t":"case","label":"Christopher v. SmithKline Beecham Corp.","cite":"567 U.S. 142","y":2012,"id":"2011/11-204","sc":1,"op":1,"sum":"The Court held that the Secretary of Labor's definition of \"outside salesman\" apply to pharmaceutical sales representatives under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"0":"5, 26","2":"2"}},{"t":"case","label":"CIGNA Corp. v. Amara","cite":"563 U.S. 421","y":2011,"id":"2010/09-804","sc":1,"sum":"The Court held that the U.S. District Court for the District of Connecticut did not have the authority to reform CIGNA's pension plan.","sumSrc":"Oyez","by":{"0":"2"}},{"t":"case","label":"Clark v. J.M. Benson Co.","cite":"789 F.2d 282","y":1986,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/789/282/","by":{"0":"27-28","1":"17, 18"}},{"t":"case","label":"Coffin v. United States","cite":"156 U.S. 432","y":1895,"id":"scdb/1894-106","sc":1,"sum":"The offence of aiding or abetting an officer of a national bank iri committing one or more of the offences set forth in Rev. Stat. § 5209 maybe committed by persons who are not officers or agents of the bank, ancl consequently it is not.necessary to aver in an indictment against such an aider or abettor that he was an officer of the bank, or occupied any spe- ciüc relation to it when committing the offence.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"2, 13"}},{"t":"case","label":"Colorado v. New Mexico","cite":"467 U.S. 310","y":1984,"id":"1983/80_orig","sc":1,"sum":"In this original action, Colorado seeks an equitable apportionment of the waters of the Vermejo River, which originates in Colorado and flows into New Mexico. Historically, all of the river's waters have been used exclusively by farm and industrial users in New Mexico. After a trial at which both States presented extensive evidence, the Special Master recommended that Colorado be allowed to divert 4,000 acre-feet of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Cruzan v. Dir., Mo. Dep’t of Health","cite":"497 U.S. 261","y":1990,"id":"1989/88-1503","sc":1,"sum":"The Court held that a Missouri state hospital had the right to keep a patient in a vegetative state alive, despite the wishes of the patient's parents, due to a lack of otherwise \"clear and convincing\" wishes on the part of the patient.","sumSrc":"Oyez","by":{"0":"14, 21, 23"}},{"t":"case","label":"Desert Palace, Inc. v. Costa","cite":"539 U.S. 90","y":2003,"id":"2002/02-679","sc":1,"sum":"The Court held that direct evidence is not required.","sumSrc":"Oyez","by":{"0":"2, 14"}},{"t":"case","label":"Desmond v. PNGI Charles Town Gaming, L.L.C.","cite":"564 F.3d 688","y":2009,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/564/688/","by":{"0":"9-10, 27"}},{"t":"case","label":"Donovan v. United Video, Inc.","cite":"725 F.2d 577","y":1984,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/725/577/","by":{"0":"28","1":"17, 18"}},{"t":"case","label":"Ellis v. Bhd. of Ry. Airline & Steamship Clerks","cite":"466 U.S. 435","y":1984,"id":"1983/82-1150","sc":1,"sum":"Section 2, Eleventh of the Railway Labor Act permits a union and an employer to require all employees in the relevant bargaining unit to join the union as a condition of continued employment. The collectivebargaining agreement between respondent national union and an airline required that all of the airline's clerical employees join the union or pay agency fees equal to members' dues. Petitioners, present or former …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"584 U.S. 79","y":2018,"id":"2017/16-1362","sc":1,"ar":2,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"0":"5, 10, 13, 22, 24-25, 29","1":"5, 19","2":"8","3":"7"}},{"t":"case","label":"Faragher v. City of Boca Raton","cite":"524 U.S. 775","y":1998,"id":"1997/97-282","sc":1,"sum":"The Court held that an employer is vicariously liable under Title VII of the Civil Rights Act of 1964 for actionable discrimination caused by a supervisor.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Gertz v. Robert Welch, Inc.","cite":"418 U.S. 323","y":1974,"id":"1973/72-617","sc":1,"op":1,"sum":"Private individuals need only prove negligence to recover in defamation suits against news media","sumSrc":"Oyez","by":{"0":"19","2":"14","3":"5"}},{"t":"case","label":"Grogan v. Garner","cite":"498 U.S. 279","y":1991,"id":"1990/89-1149","sc":1,"op":2,"ar":6,"sum":"Courts should apply the \"preponderance of the evidence\" standard. Justice John Paul Stevens, for a unanimous Supreme Court, wrote that the lack of a specified standard of evidence in section 523(a) implied that Congress had intended the preponderance of the evidence standard to be used.","sumSrc":"Oyez","by":{"0":"2, 13, 15, 18, 20","1":"9, 11-13, 16","3":"3-4, 6, 10, 13"}},{"t":"case","label":"Halo Elecs., Inc. v. Pulse Elecs., Inc.","cite":"579 U.S. 93","y":2016,"id":"2015/14-1513","sc":1,"op":1,"ar":1,"sum":"The Court determined that the rigid two-part test is not necessary for determining whether a patentee is eligible for enhanced damages under 35 U.S.C §284.","sumSrc":"Oyez","by":{"0":"15, 18, 20, 20","1":"12","3":"16"}},{"t":"case","label":"Cases—cont’d: Helix Energy Sols. Grp., Inc. v. Hewitt","cite":"598 U.S. 39","y":2023,"id":"2022/21-984","sc":1,"sum":"Respondent Hewitt was not an executive exempt from the FLSA’s overtime pay guarantee; daily-rate workers, of whatever income level, qualify as paid on a salary basis only if the conditions set out in 29 CFR §541.604(b) are met.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4, 24","2":"18","3":"8, 14"}},{"t":"case","label":"Herman & MacLean v. Huddleston","cite":"459 U.S. 375","y":1983,"id":"1982/81-680","sc":1,"op":2,"ar":1,"sum":"Alleging that they were defrauded by misrepresentations in a registration statement and prospectus for certain securities, purchasers of such securities brought a class action in Federal District Court against most of the participants in the offering, seeking recovery under § 10(b) of the Securities Exchange Act of 1934 (1934 Act), which makes it unlawful for \"any\" person to use \"any\" manipulative or deceptive …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 13-15, 20","1":"8-11","2":"12, 13","3":"3-4, 6"}},{"t":"case","label":"Lederman v. Frontier Fire Prot., Inc.","cite":"685 F.3d 1151","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/685/1151/","op":1,"by":{"0":"28","1":"18-20"}},{"t":"case","label":"Legg v. Rock Prods. Mfg. Corp.","cite":"309 F.2d 172","y":1962,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/309/172/","by":{"0":"28","1":"18"}},{"t":"case","label":"Lilienthal’s Tobacco v. United States","cite":"97 U.S. 237","y":1877,"id":"scdb/1877-132","sc":1,"op":1,"sum":"This was an information filed by the United States, March 27,1868, in the District Court for the Southern District of New York, for the condemnation and forfeiture of a quantity of manufactured tobacco, raw materials, and other personal property seized by the collector of internal revenue for the fourth collection district, March 25, 1868, at the tobacco manufactory of Christian H'. Lilienthal, in the city of New …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"2","1":"9, 16"}},{"t":"case","label":"McComb v. Farmers Reservoir & Irrigation Co.","cite":"167 F.2d 911","y":1948,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/167/911/","by":{"0":"28","1":"18"}},{"t":"case","label":"Morrison v. County of Fairfax","cite":"826 F.3d 758","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/826/758/","by":{"0":"14"}},{"t":"case","label":"N.Y. Times Co. v. Sullivan","cite":"376 U.S. 254","y":1964,"id":"1963/39","sc":1,"op":1,"sum":"The Court held that the First Amendment protects freedom of speech and freedom of the press, even about the conduct of politicians, unless the statements are made with actual malice.","sumSrc":"Oyez","by":{"0":"18-19"}},{"t":"case","label":"New York v. New Jersey","cite":"256 U.S. 296","y":1921,"id":"scdb/1920-109","sc":1,"op":1,"sum":"(1) That the right of New York to maintain such a suit on' behalf of her citizens was clear, without regard to the precise location of the boundary between the two States or to New York’s claim of jurisdiction over the waters of New York Bay.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Nishikawa v. Dulles","cite":"356 U.S. 129","y":1958,"id":"1957/19","sc":1,"op":1,"sum":"Nishikawa, a U.S. citizen, was forcibly conscripted into the Japanese Army. He was entitled to retain his American citizenship.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Octane Fitness, LLC v. ICON Health & Fitness, Inc.","cite":"572 U.S. 545","y":2014,"id":"2013/12-1184","sc":1,"op":1,"ar":1,"sum":"A case in which the Court defined \"exceptional\" cases as ones that simply stand out from others due to a frivolous nature related to its legal claims.","sumSrc":"Oyez","by":{"0":"2, 15","1":"9, 12","3":"16"}},{"t":"case","label":"Overnight Motor Transp. Co. v. Missel","cite":"316 U.S. 572","y":1942,"id":"scdb/1941-060","sc":1,"sum":"1. An employee of an interstate motor transportation company, who acted as rate clerk and performed other incidental duties, held \"engaged in commerce\" within the meaning of § 7 of the Fair Labor Standards Act of 1938, and entitled to the benefit of its overtime provisions.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","2":"18"}},{"t":"case","label":"Price Waterhouse v. Hopkins","cite":"490 U.S. 228","y":1989,"id":"1988/87-1167","sc":1,"op":5,"ar":1,"sum":"The Supreme Court held that the court of appeals applied the right test, but should have placed the burden at “preponderance of the evidence” not “clear and convincing evidence”. On remand, Price Waterhouse would escape liability if it shows it would have denied Hopkins partnership even if she were not a woman.","sumSrc":"Oyez","by":{"0":"2, 15, 19-22","1":"11-14","3":"4, 14, 16"}},{"t":"case","label":"Ramsey v. United Mine Workers","cite":"401 U.S. 302","y":1971,"id":"1970/88","sc":1,"sum":"Peti.ioner coal mine operators brought this Sherman Act conspiracy on against respondent union alleging that respondent had \"expressly or inipliedly agreed-with the major'producers to impose the provisions of the 1950 National Bituminous Coal Wage Agreement (NBCWA) on all coal mine operators, knowing that the smaller ones would be unable to meet the NBCWA terms and.wduld be driven out of business. Petitioners based …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2"}},{"t":"case","label":"Renfro v. Ind. Mich. Power Co.","cite":"497 F.3d 573","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/497/573/","op":1,"by":{"0":"28","1":"19, 20"}},{"t":"case","label":"Rivera v. Minnich","cite":"483 U.S. 574","y":1987,"id":"1986/86-98","sc":1,"sum":"Pennsylvania's preponderance standard for determining paternity is constitutionally permissible. The preponderance standard is applied most frequently in litigation between private parties in every State and, more specifically, is the standard that is applied in paternity litigation in the majority of American jurisdictions that regard such proceedings as civil in nature (as does Pennsylvania). Such a legislative …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 21"}},{"t":"case","label":"Rosenbloom v. Metromedia, Inc.","cite":"403 U.S. 29","y":1971,"id":"1970/66","sc":1,"sum":"The Supreme Court held that the knowingly and recklessly false standard applied because the story was a matter of public concern. It did not matter that Rosenbloom was a private citizen. The Court also held that the evidence in the case did not support the damages award under the proper constitutional standard.","sumSrc":"Oyez","by":{"0":"2"}},{"t":"case","label":"Cases—cont’d: Santosky v. Kramer","cite":"455 U.S. 745","y":1982,"id":"1981/80-5889","sc":1,"op":1,"sum":"Under New York law, the State may terminate, over parental objection, the rights of parents in their natural child upon a finding that the child is \"permanently neglected.\" The New York Family Court Act (§ 622) requires that only a \"fair preponderance of the evidence\" support that finding. Neglect proceedings were brought in Family Court to terminate petitioners' rights as natural parents in their three children. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 15, 18, 20-21","1":"10, 11, 14","2":"14, 15, 16, 21, 22, 23","3":"13-14"}},{"t":"case","label":"Sawyer v. Whitley","cite":"505 U.S. 333","y":1992,"id":"1991/91-6382","sc":1,"sum":"A Louisiana jury convicted petitioner Sawyer and sentenced him to death for a murder in which the victim was beaten, scalded with boiling water, and set afire. His conviction and sentence were upheld on appeal, and his petitions for state postconviction relief, as well as his first petition for federal habeas relief, were denied. In a second federal habeas petition, the District Court barred as abusive or successive …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Schneiderman v. United States","cite":"320 U.S. 118","y":1943,"id":"scdb/1942-045","sc":1,"op":1,"ar":2,"sum":"(1) That the evidence, which is reviewed in the opinion, fails to show with the requisite degree of certainty that during the period in question the defendant was not attached to the principles of the Constitution. P. 135. (2) Attachment to the principles of the Constitution is not necessarily incompatible with a desire to have it amended. P. 137. (3) Utterances of certain leaders of the party organizations in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Shockley v. City of Newport News","cite":"997 F.2d 18","y":1993,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/997/18/","by":{"0":"9, 27","1":"5, 17"}},{"t":"case","label":"Silk v. City of Chicago","cite":"194 F.3d 788","y":1999,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/194/788/","by":{"0":"21"}},{"t":"case","label":"Steadman v. SEC","cite":"450 U.S. 91","y":1981,"id":"1980/79-1266","sc":1,"sum":"After an on-the-record hearing before an Administrative Law Judge and review by the Securities and Exchange Commission (SEC) in which the preponderance-of-the-evidence standard of proof was employed, the SEC held that petitioner had violated various antifraud provisions of the federal securities laws, and sanctions were imposed. Petitioner sought review in the Court of Appeals on the alleged ground, inter alia, that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 16","1":"16","2":"12"}},{"t":"case","label":"United Mine Workers v. Gibbs","cite":"383 U.S. 715","y":1966,"id":"1965/243","sc":1,"sum":"A coal company closed a mine in Tennessee and laid off miners belonging to one of petitioner's local unions. Thereafter the company, through a subsidiary, attempted to open a new mine nearby with members of a rival union. Respondent was hired as mine superintendent and given a contract to truck coal to the nearest rail loading point. On August 15 and 16, 1960, armed members of petitioner's local forcibly prevented …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"United States v. Regan","cite":"232 U.S. 37","y":1914,"id":"scdb/1913-285","sc":1,"op":2,"ar":2,"sum":"While in strictly criminal prosecutions the jury may not return ar verdict against the defendant unless the evidence establishes his guilt beyond a reasonable doubt, in civil actions it is the duty of the jury to resolve the issues of fact according to the reasonable preponderance of the evidence, and this although they may involve a penalized or criminal act.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"2","1":"9, 12"}},{"t":"case","label":"United States v. Watson","cite":"793 F.3d 416","y":2015,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/793/416/","by":{"0":"23"}},{"t":"case","label":"Vance v. Terrazas","cite":"444 U.S. 252","y":1980,"id":"1979/78-1143","sc":1,"sum":"Section 349 (a) (2) of the Immigration and Nationality Act provides that \"a person who is a national of the United States whether by birth or naturalization, shall lose his nationality by...taking an oath or making an affirmation or other formal declaration of allegiance to a foreign state or a political subdivision thereof.\" Section 349 (c) provides that the party claiming that such loss of citizenship occurred …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","3":"11"}},{"t":"case","label":"Woodby v. INS","cite":"385 U.S. 276","y":1966,"id":"1966/40","sc":1,"sum":"No deportation order may be entered unless the Government proves by clear, unequivocal, and convincing evidence that the facts alleged as grounds for deportation are true.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","1":"10, 11","2":"11, 12, 14, 15"}},{"t":"case","label":"Yi v. Sterling Collision Ctrs., Inc.","cite":"480 F.3d 505","y":2007,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/480/505/","op":1,"by":{"0":"28","1":"19, 20"}},{"t":"usc","label":"6 U.S.C. § 1142","url":"https://www.law.cornell.edu/uscode/text/6/1142","by":{"0":"17"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","by":{"0":"18"}},{"t":"usc","label":"11 U.S.C. § 362","url":"https://www.law.cornell.edu/uscode/text/11/362","by":{"0":"17"}},{"t":"usc","label":"12 U.S.C. § 5567","url":"https://www.law.cornell.edu/uscode/text/12/5567","by":{"0":"17"}},{"t":"usc","label":"15 U.S.C. § 2087","url":"https://www.law.cornell.edu/uscode/text/15/2087","by":{"0":"16-17"}},{"t":"usc","label":"20 U.S.C. § 7946","url":"https://www.law.cornell.edu/uscode/text/20/7946","by":{"0":"17"}},{"t":"usc","label":"21 U.S.C. § 399d","url":"https://www.law.cornell.edu/uscode/text/21/399d","by":{"0":"17"}},{"t":"usc","label":"26 U.S.C. § 280G","url":"https://www.law.cornell.edu/uscode/text/26/280G","by":{"0":"17"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"2"}},{"t":"usc","label":"29 U.S.C. § 106","url":"https://www.law.cornell.edu/uscode/text/29/106","by":{"0":"16, 18"}},{"t":"usc","label":"29 U.S.C. § 464","url":"https://www.law.cornell.edu/uscode/text/29/464","by":{"0":"16"}},{"t":"usc","label":"47 U.S.C. § 532","url":"https://www.law.cornell.edu/uscode/text/47/532","by":{"0":"17"}},{"t":"usc","label":"49 U.S.C. § 30171","url":"https://www.law.cornell.edu/uscode/text/49/30171","by":{"0":"17"}},{"t":"reg","label":"29 C.F.R. § 541.301","url":"https://www.ecfr.gov/current/title-29/section-541.301","by":{"0":"26"}},{"t":"reg","label":"69 Fed. Reg. 22,122","url":"https://www.govinfo.gov/link/fr/69/22122","by":{"0":"25-26"}},{"t":"reg","label":"80 Fed. Reg. 38,516","url":"https://www.govinfo.gov/link/fr/80/38516","by":{"0":"25"}},{"t":"case","label":"Brooklyn Sav. Bank v. O’Neil","cite":"324 U.S. 697","y":1945,"id":"scdb/1944-065","sc":1,"ar":1,"sum":"1. In the absence of a bona fide dispute between the employer and the employee as to liability, an employee's written waiver of his right to liquidated damages under § 16 (b) of the Fair Labor Standards Act does not bar a subsequent action by the employee to recover such liquidated damages.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2","2":"18, 20, 21, 27, 28"}},{"t":"case","label":"Chaunt v. United States","cite":"364 U.S. 350","y":1960,"id":"1960/22","sc":1,"sum":"The Court held that the Government did not meet its standard of proof required under the Immigration and Nationality Act to revoke an order of naturalization.","sumSrc":"Oyez","by":{"1":"10, 11"}},{"t":"case","label":"Coast Van Lines, Inc. v. Armstrong","cite":"167 F.2d 705","y":1948,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/167/705/","op":1,"by":{"1":"20"}},{"t":"case","label":"Day v. Mathews","cite":"530 F.2d 1083","y":1976,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/530/1083/","by":{"1":"12"}},{"t":"case","label":"Dybach v. State of Fla., Dep’t of Corr.","cite":"942 F.2d 1562","y":1991,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/942/1562/","op":1,"by":{"1":"20"}},{"t":"case","label":"Gross v. FBL Fin. Servs., Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"sum":"The Court held that a plaintiff must show that age was the \"but-for\" cause for the defendant's action in an Age Discrimination in Employment Act claim.","sumSrc":"Oyez","by":{"1":"16","3":"3"}},{"t":"case","label":"Jones v. Virginia Oil Co.","cite":"69 Fed. Appx. 633","y":2003,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./69/633/","by":{"1":"3"}},{"t":"case","label":"Microsoft Corp. v. i4i Ltd. P’ship","cite":"564 U.S. 91","y":2011,"id":"2010/10-290","sc":1,"op":2,"ar":1,"sum":"The Court held that a challenge to a patent's validity must offer clear and convincing evidence.","sumSrc":"Oyez","by":{"1":"17","3":"10"}},{"t":"case","label":"Mt. Healthy City Sch. Dist. Bd. of Educ. v. Doyle","cite":"429 U.S. 274","y":1977,"id":"1976/75-1278","sc":1,"sum":"Writing for a unanimous Court, Justice Rehnquist held that the school district was not entitled to sovereign immunity, which generally extended to the states themselves and to state officials in their official capacities. He reasoned that the board was more akin to a municipal corporation, given its independent power to issue bonds and levy taxes.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Opp Cotton Mills v. Administrator of Wage & Hour Div. of Dep’t of Labor","cite":"312 U.S. 126","y":1941,"id":"scdb/1940-093","sc":1,"sum":"1. Wage and hours provisions of the Fair Labor Standards Act, as applied to manufacturers of textile goods for interstate commerce, held within the commerce power and consistent with the Fifth and Tenth Amendments. United States v. Darby, ante, p. 100.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"SEC v. C.M. Joiner Leasing Corp.","cite":"320 U.S. 344","y":1943,"id":"scdb/1943-006","sc":1,"by":{"1":"9"}},{"t":"case","label":"Smith v. Porter","cite":"143 F.2d 292","y":1944,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/143/292/","by":{"1":"20"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"1":"16"}},{"t":"law","label":"Pub. L. No. 88-352","url":"https://www.govinfo.gov/link/statute/78/253","by":{"1":"12, 13"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"1":"1"}},{"t":"usc","label":"29 U.S.C. § 204","url":"https://www.law.cornell.edu/uscode/text/29/204","by":{"1":"1"}},{"t":"usc","label":"29 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/29/206","stext":{"head":"§206. Minimum wage","paras":[[0,"(a) Employees engaged in commerce; home workers in Puerto Rico and Virgin Islands; employees in American Samoa; seamen on American vessels; agricultural employees"],[0,"Every employer shall pay to each of his employees who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, wages at the following rates:"],[1,"(1) except as otherwise provided in this section, not less than—"],[2,"(A) $5.85 an hour, beginning on the 60th day after May 25, 2007;"],[2,"(B) $6.55 an hour, beginning 12 months after that 60th day; and"],[2,"(C) $7.25 an hour, beginning 24 months after that 60th day;"],[1,"(2) if such employee is a home worker in Puerto Rico or the Virgin Islands, not less than the minimum piece rate prescribed by regulation or order; or, if no such minimum piece rate is in effect, any piece rate adopted by such employer which shall yield, to the proportion or class of employees prescribed by regulation or order, not less than the applicable minimum hourly wage rate. Such minimum piece rates or employer piece rates shall be commensurate with, and shall be paid in lieu of, the minimum hourly wage rate applicable under the provisions of this section. The Administrator, or his authorized representative, shall have power to make such regulations or orders as are necessary or appropriate to carry out any of the provisions of this paragraph, including the power without limiting the generality of the foregoing, to define any operation or occupation which is performed by such home work employees in Puerto Rico or the Virgin Islands; to establish minimum piece rates for any operation or occupation so defined; to prescribe the method and procedure for ascertaining and promulgating minimum piece rates; to prescribe standards for employer piece rates, including the proportion or class of employees who shall receive not less than the minimum hourly wage rate; to define the term \"home worker\"; and to prescribe the conditions under which employers, agents, contractors, and subcontractors shall cause goods to be produced by home workers;"],[1,"(3) if such employee is employed as a seaman on an American vessel, not less than the rate which will provide to the employee, for the period covered by the wage payment, wages equal to compensation at the hourly rate prescribed by paragraph (1) of this subsection for all hours during such period when he was actually on duty (including periods aboard ship when the employee was on watch or was, at the direction of a superior officer, performing work or standing by, but not including off-duty periods which are provided pursuant to the employment agreement); or"],[1,"(4) if such employee is employed in agriculture, not less than the minimum wage rate in effect under paragraph (1) after December 31, 1977."],[0,"(b) Additional applicability to employees pursuant to subsequent amendatory provisions"],[0,"Every employer shall pay to each of his employees (other than an employee to whom subsection (a)(5) 1 applies) who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, and who in such workweek is brought within the purview of this section by the amendments made to this chapter by the Fair Labor Standards Amendments of 1966, title IX of the Education Amendments of 1972 [20 U.S.C. 1681 et seq.], or the Fair Labor Standards Amendments of 1974, wages at the following rate: Effective after December 31, 1977, not less than the minimum wage rate in effect under subsection (a)(1)."],[0,"(c) Repealed. Pub. L. 104–188, [title II], §2104(c), Aug. 20, 1996, 110 Stat. 1929"],[0,"(d) Prohibition of sex discrimination"],[0,"(1) No employer having employees subject to any provisions of this section shall discriminate, within any establishment in which such employees are employed, between employees on the basis of sex by paying wages to employees in such establishment at a rate less than the rate at which he pays wages to employees of the opposite sex in such establishment for equal work on jobs the performance of which requires equal skill, effort, and responsibility, and which are performed under similar working conditions, except where such payment is made pursuant to (i) a seniority system; (ii) a merit system; (iii) a system which measures earnings by quantity or quality of production; or (iv) a differential based on any other factor other than sex: Provided, That an employer who is paying a wage rate differential in violation of this subsection shall not, in order to comply with the provisions of this subsection, reduce the wage rate of any employee."],[0,"(2) No labor organization, or its agents, representing employees of an employer having employees subject to any provisions of this section shall cause or attempt to cause such an employer to discriminate against an employee in violation of paragraph (1) of this subsection."],[0,"(3) For purposes of administration and enforcement, any amounts owing to any employee which have been withheld in violation of this subsection shall be deemed to be unpaid minimum wages or unpaid overtime compensation under this chapter."],[0,"(4) As used in this subsection, the term \"labor organization\" means any organization of any kind, or any agency or employee representation committee or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours of employment, or conditions of work."],[0,"(e) Employees of employers providing contract services to United States"],[0,"(1) Notwithstanding the provisions of section 213 of this title (except subsections (a)(1) and (f) thereof), every employer providing any contract services (other than linen supply services) under a contract with the United States or any subcontract thereunder shall pay to each of his employees whose rate of pay is not governed by chapter 67 of title 41 or to whom subsection (a)(1) of this section is not applicable, wages at rates not less than the rates provided for in subsection (b) of this section."],[0,"(2) Notwithstanding the provisions of section 213 of this title (except subsections (a)(1) and (f) thereof) and the provisions of chapter 67 of title 41, every employer in an establishment providing linen supply services to the United States under a contract with the United States or any subcontract thereunder shall pay to each of his employees in such establishment wages at rates not less than those prescribed in subsection (b), except that if more than 50 per centum of the gross annual dollar volume of sales made or business done by such establishment is derived from providing such linen supply services under any such contracts or subcontracts, such employer shall pay to each of his employees in such establishment wages at rates not less than those prescribed in subsection (a)(1) of this section."],[0,"(f) Employees in domestic service"],[0,"Any employee—"],[1,"(1) who in any workweek is employed in domestic service in a household shall be paid wages at a rate not less than the wage rate in effect under subsection (b) unless such employee's compensation for such service would not because of section 209(a)(6) of the Social Security Act [42 U.S.C. 409(a)(6)] constitute wages for the purposes of title II of such Act [42 U.S.C. 401 et seq.], or"],[1,"(2) who in any workweek—"],[2,"(A) is employed in domestic service in one or more households, and"],[2,"(B) is so employed for more than 8 hours in the aggregate,"],[0,"shall be paid wages for such employment in such workweek at a rate not less than the wage rate in effect under subsection (b)."],[0,"(g) Newly hired employees who are less than 20 years old"],[0,"(1) In lieu of the rate prescribed by subsection (a)(1), any employer may pay any employee of such employer, during the first 90 consecutive calendar days after such employee is initially employed by such employer, a wage which is not less than $4.25 an hour."],[0,"(2) In lieu of the rate prescribed by subsection (a)(1), the Governor of Puerto Rico, subject to the approval of the Financial Oversight and Management Board established pursuant to section 2121 of title 48, may designate a time period not to exceed four years during which employers in Puerto Rico may pay employees who are initially employed after June 30, 2016, a wage which is not less than the wage described in paragraph (1). Notwithstanding the time period designated, such wage shall not continue in effect after such Board terminates in accordance with section 2149 of title 48."],[0,"(3) No employer may take any action to displace employees (including partial displacements such as reduction in hours, wages, or employment benefits) for purposes of hiring individuals at the wage authorized in paragraph (1) or (2)."],[0,"(4) Any employer who violates this subsection shall be considered to have violated section 215(a)(3) of this title."],[0,"(5) This subsection shall only apply to an employee who has not attained the age of 20 years, except in the case of the wage applicable in Puerto Rico, 25 years, until such time as the Board described in paragraph (2) terminates in accordance with section 2149 of title 48."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/206?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§206. Minimum wage","tname":"Labor","by":{"1":"2","2":"2"}},{"t":"usc","label":"29 U.S.C. § 207","url":"https://www.law.cornell.edu/uscode/text/29/207","stext":{"head":"§207. Maximum hours","paras":[[0,"(a) Employees engaged in interstate commerce; additional applicability to employees pursuant to subsequent amendatory provisions"],[0,"(1) Except as otherwise provided in this section, no employer shall employ any of his employees who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, for a workweek longer than forty hours unless such employee receives compensation for his employment in excess of the hours above specified at a rate not less than one and one-half times the regular rate at which he is employed."],[0,"(2) No employer shall employ any of his employees who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, and who in such workweek is brought within the purview of this subsection by the amendments made to this chapter by the Fair Labor Standards Amendments of 1966—"],[1,"(A) for a workweek longer than forty-four hours during the first year from the effective date of the Fair Labor Standards Amendments of 1966,"],[1,"(B) for a workweek longer than forty-two hours during the second year from such date, or"],[1,"(C) for a workweek longer than forty hours after the expiration of the second year from such date,"],[0,"unless such employee receives compensation for his employment in excess of the hours above specified at a rate not less than one and one-half times the regular rate at which he is employed."],[0,"(b) Employment pursuant to collective bargaining agreement; employment by independently owned and controlled local enterprise engaged in distribution of petroleum products"],[0,"No employer shall be deemed to have violated subsection (a) by employing any employee for a workweek in excess of that specified in such subsection without paying the compensation for overtime employment prescribed therein if such employee is so employed—"],[1,"(1) in pursuance of an agreement, made as a result of collective bargaining by representatives of employees certified as bona fide by the National Labor Relations Board, which provides that no employee shall be employed more than one thousand and forty hours during any period of twenty-six consecutive weeks; or"],[1,"(2) in pursuance of an agreement, made as a result of collective bargaining by representatives of employees certified as bona fide by the National Labor Relations Board, which provides that during a specified period of fifty-two consecutive weeks the employee shall be employed not more than two thousand two hundred and forty hours and shall be guaranteed not less than one thousand eight hundred and forty-hours (or not less than forty-six weeks at the normal number of hours worked per week, but not less than thirty hours per week) and not more than two thousand and eighty hours of employment for which he shall receive compensation for all hours guaranteed or worked at rates not less than those applicable under the agreement to the work performed and for all hours in excess of the guaranty which are also in excess of the maximum workweek applicable to such employee under subsection (a) or two thousand and eighty in such period at rates not less than one and one-half times the regular rate at which he is employed; or"],[1,"(3) by an independently owned and controlled local enterprise (including an enterprise with more than one bulk storage establishment) engaged in the wholesale or bulk distribution of petroleum products if—"],[2,"(A) the annual gross volume of sales of such enterprise is less than $1,000,000 exclusive of excise taxes,"],[2,"(B) more than 75 per centum of such enterprise's annual dollar volume of sales is made within the State in which such enterprise is located, and"],[2,"(C) not more than 25 per centum of the annual dollar volume of sales of such enterprise is to customers who are engaged in the bulk distribution of such products for resale,"],[1,"and such employee receives compensation for employment in excess of forty hours in any workweek at a rate not less than one and one-half times the minimum wage rate applicable to him under section 206 of this title,"],[0,"and if such employee receives compensation for employment in excess of twelve hours in any workday, or for employment in excess of fifty-six hours in any workweek, as the case may be, at a rate not less than one and one-half times the regular rate at which he is employed."],[0,"(c), (d) Repealed. Pub. L. 93–259, §19(e), Apr. 8, 1974, 88 Stat. 66"],[0,"(e) \"Regular rate\" defined"],[0,"As used in this section the \"regular rate\" at which an employee is employed shall be deemed to include all remuneration for employment paid to, or on behalf of, the employee, but shall not be deemed to include—"],[1,"(1) sums paid as gifts; payments in the nature of gifts made at Christmas time or on other special occasions, as a reward for service, the amounts of which are not measured by or dependent on hours worked, production, or efficiency;"],[1,"(2) payments made for occasional periods when no work is performed due to vacation, holiday, illness, failure of the employer to provide sufficient work, or other similar cause; reasonable payments for traveling expenses, or other expenses, incurred by an employee in the furtherance of his employer's interests and properly reimbursable by the employer; and other similar payments to an employee which are not made as compensation for his hours of employment;"],[1,"(3) Sums 1 paid in recognition of services performed during a given period if either, (a) both the fact that payment is to be made and the amount of the payment are determined at the sole discretion of the employer at or near the end of the period and not pursuant to any prior contract, agreement, or promise causing the employee to expect such payments regularly; or (b) the payments are made pursuant to a bona fide profit-sharing plan or trust or bona fide thrift or savings plan, meeting the requirements of the Administrator set forth in appropriate regulations which he shall issue, having due regard among other relevant factors, to the extent to which the amounts paid to the employee are determined without regard to hours of work, production, or efficiency; or (c) the payments are talent fees (as such talent fees are defined and delimited by regulations of the Administrator) paid to performers, including announcers, on radio and television programs;"],[1,"(4) contributions irrevocably made by an employer to a trustee or third person pursuant to a bona fide plan for providing old-age, retirement, life, accident, or health insurance or similar benefits for employees;"],[1,"(5) extra compensation provided by a premium rate paid for certain hours worked by the employee in any day or workweek because such hours are hours worked in excess of eight in a day or in excess of the maximum workweek applicable to such employee under subsection (a) or in excess of the employee's normal working hours or regular working hours, as the case may be;"],[1,"(6) extra compensation provided by a premium rate paid for work by the employee on Saturdays, Sundays, holidays, or regular days of rest, or on the sixth or seventh day of the workweek, where such premium rate is not less than one and one-half times the rate established in good faith for like work performed in nonovertime hours on other days;"],[1,"(7) extra compensation provided by a premium rate paid to the employee, in pursuance of an applicable employment contract or collective-bargaining agreement, for work outside of the hours established in good faith by the contract or agreement as the basic, normal, or regular workday (not exceeding eight hours) or workweek (not exceeding the maximum workweek applicable to such employee under subsection (a),2 where such premium rate is not less than one and one-half times the rate established in good faith by the contract or agreement for like work performed during such workday or workweek; or"],[1,"(8) any value or income derived from employer-provided grants or rights provided pursuant to a stock option, stock appreciation right, or bona fide employee stock purchase program which is not otherwise excludable under any of paragraphs (1) through (7) if—"],[2,"(A) grants are made pursuant to a program, the terms and conditions of which are communicated to participating employees either at the beginning of the employee's participation in the program or at the time of the grant;"],[2,"(B) in the case of stock options and stock appreciation rights, the grant or right cannot be exercisable for a period of at least 6 months after the time of grant (except that grants or rights may become exercisable because of an employee's death, disability, retirement, or a change in corporate ownership, or other circumstances permitted by regulation), and the exercise price is at least 85 percent of the fair market value of the stock at the time of grant;"],[2,"(C) exercise of any grant or right is voluntary; and"],[2,"(D) any determinations regarding the award of, and the amount of, employer-provided grants or rights that are based on performance are—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/207?type=usc&year=mostrecent&link-type=html"},"head":"§207. Maximum hours","tname":"Labor","by":{"1":"2","2":"2"}},{"t":"usc","label":"29 U.S.C. § 211","url":"https://www.law.cornell.edu/uscode/text/29/211","subs":["(a)","(c)"],"stext":{"head":"§211. Collection of data","paras":[[0,"(a) Investigations and inspections"],[0,"The Administrator or his designated representatives may investigate and gather data regarding the wages, hours, and other conditions and practices of employment in any industry subject to this chapter, and may enter and inspect such places and such records (and make such transcriptions thereof), question such employees, and investigate such facts, conditions, practices, or matters as he may deem necessary or appropriate to determine whether any person has violated any provision of this chapter, or which may aid in the enforcement of the provisions of this chapter. Except as provided in section 212 of this title and in subsection (b) of this section, the Administrator shall utilize the bureaus and divisions of the Department of Labor for all the investigations and inspections necessary under this section. Except as provided in section 212 of this title, the Administrator shall bring all actions under section 217 of this title to restrain violations of this chapter."],[0,"(b) State and local agencies and employees"],[0,"With the consent and cooperation of State agencies charged with the administration of State labor laws, the Administrator and the Secretary of Labor may, for the purpose of carrying out their respective functions and duties under this chapter, utilize the services of State and local agencies and their employees and, notwithstanding any other provision of law, may reimburse such State and local agencies and their employees for services rendered for such purposes."],[0,"(c) Records"],[0,"Every employer subject to any provision of this chapter or of any order issued under this chapter shall make, keep, and preserve such records of the persons employed by him and of the wages, hours, and other conditions and practices of employment maintained by him, and shall preserve such records for such periods of time, and shall make such reports therefrom to the Administrator as he shall prescribe by regulation or order as necessary or appropriate for the enforcement of the provisions of this chapter or the regulations or orders thereunder. The employer of an employee who performs substitute work described in section 207(p)(3) of this title may not be required under this subsection to keep a record of the hours of the substitute work."],[0,"(d) Homework regulations"],[0,"The Administrator is authorized to make such regulations and orders regulating, restricting, or prohibiting industrial homework as are necessary or appropriate to prevent the circumvention or evasion of and to safeguard the minimum wage rate prescribed in this chapter, and all existing regulations or orders of the Administrator relating to industrial homework are continued in full force and effect."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/211?type=usc&year=mostrecent&link-type=html"},"head":"§211. Collection of data","tname":"Labor","by":{"1":"1","2":"21"}},{"t":"usc","label":"29 U.S.C. § 213","url":"https://www.law.cornell.edu/uscode/text/29/213","subs":["(a)","(a)(1)"],"stext":{"head":"§213. Exemptions","paras":[[0,"(a) Minimum wage and maximum hour requirements"],[0,"The provisions of sections 206 (except subsection (d) in the case of paragraph (1) of this subsection) and 207 of this title shall not apply with respect to—"],[1,"(1) any employee employed in a bona fide executive, administrative, or professional capacity (including any employee employed in the capacity of academic administrative personnel or teacher in elementary or secondary schools), or in the capacity of outside salesman (as such terms are defined and delimited from time to time by regulations of the Secretary, subject to the provisions of subchapter II of chapter 5 of title 5, except that an employee of a retail or service establishment shall not be excluded from the definition of employee employed in a bona fide executive or administrative capacity because of the number of hours in his workweek which he devotes to activities not directly or closely related to the performance of executive or administrative activities, if less than 40 per centum of his hours worked in the workweek are devoted to such activities); or"],[1,"(2) Repealed. Pub. L. 101–157, §3(c)(1), Nov. 17, 1989, 103 Stat. 939."],[1,"(3) any employee employed by an establishment which is an amusement or recreational establishment, organized camp, or religious or non-profit educational conference center, if (A) it does not operate for more than seven months in any calendar year, or (B) during the preceding calendar year, its average receipts for any six months of such year were not more than 331/3 per centum of its average receipts for the other six months of such year, except that the exemption from sections 206 and 207 of this title provided by this paragraph does not apply with respect to any employee of a private entity engaged in providing services or facilities (other than, in the case of the exemption from section 206 of this title, a private entity engaged in providing services and facilities directly related to skiing) in a national park or a national forest, or on land in the National Wildlife Refuge System, under a contract with the Secretary of the Interior or the Secretary of Agriculture; or"],[1,"(4) Repealed. Pub. L. 101–157, §3(c)(1), Nov. 17, 1989, 103 Stat. 939."],[1,"(5) any employee employed in the catching, taking, propagating, harvesting, cultivating, or farming of any kind of fish, shellfish, crustacea, sponges, seaweeds, or other aquatic forms of animal and vegetable life, or in the first processing, canning or packing such marine products at sea as an incident to, or in conjunction with, such fishing operations, including the going to and returning from work and loading and unloading when performed by any such employee; or"],[1,"(6) any employee employed in agriculture (A) if such employee is employed by an employer who did not, during any calendar quarter during the preceding calendar year, use more than five hundred man-days of agricultural labor, (B) if such employee is the parent, spouse, child, or other member of his employer's immediate family, (C) if such employee (i) is employed as a hand harvest laborer and is paid on a piece rate basis in an operation which has been, and is customarily and generally recognized as having been, paid on a piece rate basis in the region of employment, (ii) commutes daily from his permanent residence to the farm on which he is so employed, and (iii) has been employed in agriculture less than thirteen weeks during the preceding calendar year, (D) if such employee (other than an employee described in clause (C) of this subsection) (i) is sixteen years of age or under and is employed as a hand harvest laborer, is paid on a piece rate basis in an operation which has been, and is customarily and generally recognized as having been, paid on a piece rate basis in the region of employment, (ii) is employed on the same farm as his parent or person standing in the place of his parent, and (iii) is paid at the same piece rate as employees over age sixteen are paid on the same farm, or (E) if such employee is principally engaged in the range production of livestock; or"],[1,"(7) any employee to the extent that such employee is exempted by regulations, order, or certificate of the Secretary issued under section 214 of this title; or"],[1,"(8) any employee employed in connection with the publication of any weekly, semiweekly, or daily newspaper with a circulation of less than four thousand the major part of which circulation is within the county where published or counties contiguous thereto; or"],[1,"(9) Repealed. Pub. L. 93–259, §23(a)(1), Apr. 8, 1974, 88 Stat. 69."],[1,"(10) any switchboard operator employed by an independently owned public telephone company which has not more than seven hundred and fifty stations; or"],[1,"(11) Repealed. Pub. L. 93–259, §10(a), Apr. 8, 1974, 88 Stat. 63."],[1,"(12) any employee employed as a seaman on a vessel other than an American vessel; or"],[1,"(13), (14) Repealed. Pub. L. 93–259, §§9(b)(1), 23(b)(1), Apr. 8, 1974, 88 Stat. 63, 69."],[1,"(15) any employee employed on a casual basis in domestic service employment to provide babysitting services or any employee employed in domestic service employment to provide companionship services for individuals who (because of age or infirmity) are unable to care for themselves (as such terms are defined and delimited by regulations of the Secretary); or"],[1,"(16) a criminal investigator who is paid availability pay under section 5545a of title 5;"],[1,"(17) any employee who is a computer systems analyst, computer programmer, software engineer, or other similarly skilled worker, whose primary duty is—"],[2,"(A) the application of systems analysis techniques and procedures, including consulting with users, to determine hardware, software, or system functional specifications;"],[2,"(B) the design, development, documentation, analysis, creation, testing, or modification of computer systems or programs, including prototypes, based on and related to user or system design specifications;"],[2,"(C) the design, documentation, testing, creation, or modification of computer programs related to machine operating systems; or"],[2,"(D) a combination of duties described in subparagraphs (A), (B), and (C) the performance of which requires the same level of skills, and"],[1,"who, in the case of an employee who is compensated on an hourly basis, is compensated at a rate of not less than $27.63 an hour; or"],[1,"(18) any employee who is a border patrol agent, as defined in section 5550(a) of title 5; or"],[1,"(19) any employee employed to play baseball who is compensated pursuant to a contract that provides for a weekly salary for services performed during the league's championship season (but not spring training or the off season) at a rate that is not less than a weekly salary equal to the minimum wage under section 206(a) of this title for a workweek of 40 hours, irrespective of the number of hours the employee devotes to baseball related activities."],[0,"(b) Maximum hour requirements"],[0,"The provisions of section 207 of this title shall not apply with respect to—"],[1,"(1) any employee with respect to whom the Secretary of Transportation has power to establish qualifications and maximum hours of service pursuant to the provisions of section 31502 of title 49; or"],[1,"(2) any employee of an employer engaged in the operation of a rail carrier subject to part A of subtitle IV of title 49; or"],[1,"(3) any employee of a carrier by air subject to the provisions of title II of the Railway Labor Act [45 U.S.C. 181 et seq.]; or"],[1,"(4) Repealed. Pub. L. 93–259, §11(c), Apr. 8, 1974, 88 Stat. 64."],[1,"(5) any individual employed as an outside buyer of poultry, eggs, cream, or milk, in their raw or natural state; or"],[1,"(6) any employee employed as a seaman; or"],[1,"(7) Repealed. Pub. L. 93–259, §21(b)(3), Apr. 8, 1974, 88 Stat. 68."],[1,"(8) Repealed. Pub. L. 95–151, §14(b), Nov. 1, 1977, 91 Stat. 1252."],[1,"(9) any employee employed as an announcer, news editor, or chief engineer by a radio or television station the major studio of which is located (A) in a city or town of one hundred thousand population or less, according to the latest available decennial census figures as compiled by the Bureau of the Census, except where such city or town is part of a standard metropolitan statistical area, as defined and designated by the Office of Management and Budget, which has a total population in excess of one hundred thousand, or (B) in a city or town of twenty-five thousand population or less, which is part of such an area but is at least 40 airline miles from the principal city in such area; or"],[1,"(10)(A) any salesman, partsman, or mechanic primarily engaged in selling or servicing automobiles, trucks, or farm implements, if he is employed by a nonmanufacturing establishment primarily engaged in the business of selling such vehicles or implements to ultimate purchasers; or"],[1,"(B) any salesman primarily engaged in selling trailers, boats, or aircraft, if he is employed by a nonmanufacturing establishment primarily engaged in the business of selling trailers, boats, or aircraft to ultimate purchasers; or"],[1,"(11) any employee employed as a driver or driver's helper making local deliveries, who is compensated for such employment on the basis of trip rates, or other delivery payment plan, if the Secretary shall find that such plan has the general purpose and effect of reducing hours worked by such employees to, or below, the maximum workweek applicable to them under section 207(a) of this title; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/213?type=usc&year=mostrecent&link-type=html"},"head":"§213. Exemptions","tname":"Labor","by":{"1":"2, 2","2":"2, 2, 4","3":"14"}},{"t":"usc","label":"29 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/29/216","subs":["(a)"],"by":{"1":"1"}},{"t":"usc","label":"29 U.S.C. § 217","url":"https://www.law.cornell.edu/uscode/text/29/217","by":{"1":"1"}},{"t":"usc","label":"25 U.S.C. § 2504","url":"https://www.law.cornell.edu/uscode/text/25/2504","subs":["(b)(2)(B)"],"by":{"1":"16"}},{"t":"usc","label":"29 U.S.C. § 722","url":"https://www.law.cornell.edu/uscode/text/29/722","subs":["(a)(3)(A)(ii)"],"by":{"1":"16"}},{"t":"case","label":"Aoude v. Mobil Oil Corp.","cite":"892 F.2d 1115","y":1989,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/892/1115/","by":{"2":"15"}},{"t":"case","label":"Barrentine v. Arkansas-Best Freight Systems, Inc.","cite":"450 U.S. 728","y":1981,"id":"1980/79-2006","sc":1,"sum":"Petitioners' wage claims under the FLSA are not barred by the prior submission of their grievances to the contractual dispute-resolution procedures.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19, 20, 21","3":"9"}},{"t":"case","label":"Boaz v. FedEx Customer Information Services, Inc.","cite":"725 F.3d 603","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/725/603/","by":{"2":"20"}},{"t":"case","label":"Chicca v. St. Luke’s Episcopal Health System","cite":"858 F. Supp. 2d 777","y":2012,"court":"S.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/858/777/","sum":"Noting that “general job descriptions … prepared by the employer may be considered” in ascertaining an employee’s primary duty.","sumSrc":"brief:2","by":{"2":"22"}},{"t":"case","label":"Citicorp Industrial Credit, Inc. v. Brock","cite":"483 U.S. 27","y":1987,"id":"1986/86-88","sc":1,"sum":"Section 15(a)(1) applies to secured creditors who acquire \"hot goods\" pursuant to a security agreement.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17, 18","3":"10"}},{"t":"case","label":"Concrete Pipe & Products of California, Inc. v. Construction Laborers Pension Trust for Southern California","cite":"508 U.S. 602","y":1993,"id":"1992/91-904","sc":1,"sum":"The Multiemployer Pension Plan Amendments Act of 1980 (MPPAA) amended the Employee Retirement Income Security Act of 1974 (ERISA) to provide that in certain circumstances an employer withdrawing from a multiemployer plan incurs as \"withdrawal liability\" a share of the plan's unfunded vested benefits, 29 U. S. C. §§ 1381, 1391. Withdrawal liability is assessed by means of a notification by the \"plan sponsor\" and a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"D.A. Schulte, Inc. v. Gangi","cite":"328 U.S. 108","y":1946,"id":"scdb/1945-063","sc":1,"sum":". An employer can not be'relieved from liability for liquidated damages under § 16 (b) of the Fair Labor Standards Act by a compromise or settlement of a bona fide dispute as to the coverage of the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19, 20"}},{"t":"case","label":"Davis v. Food Lion","cite":"792 F.2d 1274","y":1986,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/792/1274/","by":{"2":"3"}},{"t":"case","label":"Hodgson v. Brookhaven General Hospital","cite":"436 F.2d 719","y":1970,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/436/719/","by":{"2":"22"}},{"t":"case","label":"Hodgson v. Hotard","cite":"436 F.2d 1110","y":1971,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/436/1110/","by":{"2":"18"}},{"t":"case","label":"Integrity Staffing Solutions, Inc. v. Busk","cite":"574 U.S. 27","y":2014,"id":"2014/13-433","sc":1,"sum":"The Court ruled that employees of Integrity Staffing Solutions, Inc. could not be compensated for time spent passing through security checkpoints, because the checkpoints were not integral to their principal duties as employees.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Killion v. KeHE Distributors, LLC","cite":"761 F.3d 574","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/761/574/","by":{"2":"6, 25, 26"}},{"t":"case","label":"Marsh v. J. Alexander’s LLC","cite":"905 F.3d 610","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/905/610/","by":{"2":"16"}},{"t":"case","label":"Metropolitan Stevedore Co. v. Rambo","cite":"521 U.S. 121","y":1997,"id":"1996/96-272","sc":1,"sum":"The Court held that nominal compensation is proper when there is a significant possibility that the worker's wage-earning capacity will fall below the level of his pre-injury wages sometime in the future.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Morrison v. Circuit City Stores, Inc.","cite":"317 F.3d 646","y":2003,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/317/646/","by":{"2":"20"}},{"t":"case","label":"Powell v. U.S. Cartridge Co.","cite":"339 U.S. 497","y":1950,"id":"scdb/1949-075","sc":1,"sum":"The Fair Labor Standards. Act applies to employees of a private contractor operating a Government-owned munitions plant under a cost-plus-a-fixed-fee contract with the Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17"}},{"t":"case","label":"Sanchez v. Ultimo, LLC","cite":"2024 WL 3633696","y":2024,"court":"D.D.C. Aug. 2","by":{"2":"22","3":"13"}},{"t":"case","label":"Shepherd v. American Broadcasting Cos.","cite":"62 F.3d 1469","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/62/1469/","by":{"2":"15","3":"6"}},{"t":"case","label":"Smith v. Johnson & Johnson","cite":"593 F.3d 280","y":2010,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/593/280/","sum":"Concluding that employee was exempt under the administrative exemption in part because her job description required her “to plan and prioritize her responsibilities in a manner that maximized business results”.","sumSrc":"brief:2","by":{"2":"21"}},{"t":"case","label":"Speiser v. Randall","cite":"357 U.S. 513","y":1958,"id":"1957/483","sc":1,"sum":"Enforcement of this provision through procedures which place the burdens of proof and persuasion on the taxpayers denied them freedom of speech without the procedural safeguards required by the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12, 13"}},{"t":"case","label":"Taylor v. Grubbs","cite":"930 F.3d 611","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/930/611/","by":{"2":"9"}},{"t":"case","label":"Tennessee Coal, Iron & Railroad Co. v. Muscoda Local No. 123","cite":"321 U.S. 590","y":1944,"id":"scdb/1943-089","sc":1,"sum":"1. The Fair Labor Standards Act is remedial and humanitarian in nature and must not be interpreted or applied in a narrow, grudging manner.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17"}},{"t":"case","label":"Tony & Susan Alamo Foundation v. Secretary of Labor","cite":"471 U.S. 290","y":1985,"id":"1984/83-1935","sc":1,"sum":"Petitioner Foundation is a nonprofit religious organization that derives its income largely from the operation of commercial businesses staffed by the Foundation's \"associates,\" most of whom were drug addicts, derelicts, or criminals before their rehabilitation by the Foundation. These workers receive no cash salaries, but the Foundation provides them with food, clothing, shelter, and other benefits. The Secretary …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"Warnebold v. Union Pacific Railroad","cite":"963 F.2d 222","y":1992,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/963/222/","by":{"2":"20"}},{"t":"case","label":"Wirtz v. Milton J. Wershow Co.","cite":"416 F.2d 1071","y":1969,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/416/1071/","by":{"2":"18"}},{"t":"case","label":"Wysocki v. International Business Machine Corp.","cite":"607 F.3d 1102","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/607/1102/","sum":"Holding that a waiver of rights under the Uniformed Services Employment and Reemployment Rights Act is valid where the release “used clear and unambiguous language and involved a valuable amount of consideration”.","sumSrc":"brief:2","by":{"2":"20"}},{"t":"usc","label":"29 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/29/202","subs":["(a)","(b)"],"by":{"2":"1, 17, 18, 28, 1, 10, 17, 19"}},{"t":"reg","label":"5 C.F.R. § 551.202","url":"https://www.ecfr.gov/current/title-5/section-551.202","subs":["(d)"],"by":{"2":"19","3":"9"}},{"t":"reg","label":"29 C.F.R. § 541.500","url":"https://www.ecfr.gov/current/title-29/section-541.500","subs":["(a)"],"by":{"2":"2"}},{"t":"case","label":"Arbaugh v. Y&H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"3":"11"}},{"t":"case","label":"Broidy Cap. Mgmt. LLC v. Benomar","cite":"944 F.3d 436","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/944/436/","by":{"3":"11"}},{"t":"case","label":"CRST Van Expedited, Inc. v. EEOC","cite":"578 U.S. 419","y":2016,"id":"2015/14-1375","sc":1,"sum":"The Court determined that a defendant may be a “prevailing party” for the purpose of the award of fees even without a ruling on the merits.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"Echo Powerline, L.L.C. v. OSHRC","cite":"968 F.3d 471","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/968/471/","by":{"3":"11"}},{"t":"case","label":"Harris v. Kellogg Brown & Root Servs.","cite":"724 F.3d 458","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/724/458/","by":{"3":"12"}},{"t":"case","label":"Hickman v. Taylor","cite":"329 U.S. 495","y":1947,"id":"scdb/1946-035","sc":1,"sum":"Under the Federal Rules of Civil Procedure, plaintiff in a suit in a federal district court against certain tug owners to recover for the death of a seaman in the sinking of the tug filed numerous interrogatories directed to the defendants, including one inquiring whether any statements of members of the crew were taken in connection with the accident and requesting that exact copies of all such written statements …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"12"}},{"t":"case","label":"Lynn’s Food Stores, Inc. v. United States","cite":"679 F.2d 1350","y":1982,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/679/1350/","by":{"3":"9"}},{"t":"case","label":"Cases—cont’d: Morgan v. Family Dollar Stores, Inc.","cite":"551 F.3d 1233","y":2008,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/551/1233/","by":{"3":"13"}},{"t":"case","label":"Murray v. UBS Sec., LLC","cite":"601 U.S. 23","y":2024,"id":"2023/22-660","sc":1,"op":1,"sum":"A whistleblower seeking to invoke the protections of the Sarbanes-Oxley Act—18 U. S. C. §1514A(a)—must prove that their protected activity was a contributing factor in the employer’s unfavorable personnel action, but need not prove that the employer acted with “retaliatory intent.”","sumSrc":"Holding (supremecourt.gov)","by":{"3":"12"}},{"t":"case","label":"NLRB v. Transp. Mgmt. Co.","cite":"462 U.S. 393","y":1983,"id":"1982/82-168","sc":1,"op":2,"ar":1,"sum":"Acting on unfair labor practice charges filed by an employee of respondent, petitioner National Labor Relations Board found that respondent had discharged the employee, a busdriver, for his union activities, in violation of §§ 8(a)(1) and 8(a)(3) of the National Labor Relations Act. The Board applied its rule that the General Counsel has the burden of persuading the Board by a preponderance of the evidence that an …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"11"}},{"t":"case","label":"Peretz v. United States","cite":"501 U.S. 923","y":1991,"id":"1990/90-615","sc":1,"sum":"In Gomez v. United States, 490 U. S. 858, this Court held that the selection of a jury in a felony trial without a defendant's consent is not one of the \"additional duties\" that magistrates may be assigned under the Federal Magistrates Act. That decision rested on the lack of both an express statutory provision for de novo review and an explicit congressional intent to permit magistrates to conduct voir dire absent …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"10"}},{"t":"case","label":"Ramirez v. T&H Lemont, Inc.","cite":"845 F.3d 772","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/845/772/","by":{"3":"6"}},{"t":"case","label":"United States ex rel. Vuyyuru v. Jadhav","cite":"555 F.3d 337","y":2009,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/555/337/","by":{"3":"12"}},{"t":"case","label":"Wellness Int’l Network, Ltd. v. Sharif","cite":"575 U.S. 665","y":2015,"id":"2014/13-935","sc":1,"sum":"The Court held that claims that would normally be adjudicated by an Article III court can be adjudicated in a non-Article III court as long as the parties knowingly and voluntarily consent.","sumSrc":"Oyez","by":{"3":"9"}},{"t":"usc","label":"8 U.S.C. § 1229c","url":"https://www.law.cornell.edu/uscode/text/8/1229c","by":{"3":"10"}},{"t":"usc","label":"10 U.S.C. § 987","url":"https://www.law.cornell.edu/uscode/text/10/987","by":{"3":"12"}},{"t":"usc","label":"15 U.S.C. § 1693h","url":"https://www.law.cornell.edu/uscode/text/15/1693h","by":{"3":"12"}},{"t":"rule","label":"Fed. R. Civ. P. 26","url":"https://www.law.cornell.edu/rules/frcp/rule_26","by":{"3":"13"}}]};